create_causal_mask.source:
def create_causal_mask(N: int, offset: int=0, window_size: Optional[int]=None, right_padding: Optional[mx.array]=None, left_padding: Optional[mx.array]=None):
    rinds = mx.arange(offset + N)
    linds = mx.arange(offset, offset + N) if offset else rinds
    linds = linds[:, None]
    rinds = rinds[None]
    mask = linds >= rinds
    if window_size is not None:
        mask = mask & (linds < rinds + window_size)
    if right_padding is not None:
        mask = mask & (rinds < mx.expand_dims(offset + N - right_padding, (1, 2, 3)))
    if left_padding is not None:
        mask = mask & (mx.expand_dims(left_padding, (1, 2, 3)) <= rinds)
    return mask

create_attention_mask.source:
def create_attention_mask(h, cache=None, window_size: Optional[int]=None, return_array: bool=False):
    N = h.shape[1]
    if cache and hasattr(cache, 'make_mask'):
        return cache.make_mask(N, return_array=return_array, window_size=window_size)
    if N == 1:
        return None
    if return_array or (window_size and N > window_size):
        return create_causal_mask(N, window_size=window_size)
    return 'causal'

scaled_dot_product_attention.source:
def scaled_dot_product_attention(queries, keys, values, cache, scale: float, mask: Optional[mx.array], sinks: Optional[mx.array]=None) -> mx.array:
    if hasattr(cache, 'bits'):
        if sinks is not None:
            raise ValueError('Quantized SDPA does not support attention sinks.')
        return quantized_scaled_dot_product_attention(queries, keys, values, scale=scale, mask=mask, group_size=cache.group_size, bits=cache.bits)
    else:
        return mx.fast.scaled_dot_product_attention(queries, keys, values, scale=scale, mask=mask, sinks=sinks)

create_attention_mask.source:
def create_attention_mask(N: int, offset: int, return_array: bool, window_size: Optional[int]):
    if window_size is not None:
        return create_causal_mask(N, offset, window_size=window_size)
    elif N == 1:
        return None
    elif return_array:
        return create_causal_mask(N, offset, window_size=window_size)
    else:
        return 'causal'

_BaseCache.source:
class _BaseCache:

    @property
    def state(self):
        return []

    @state.setter
    def state(self, v):
        if v is not None and v:
            raise ValueError('This cache has no state but a state was set.')

    def is_trimmable(self):
        return False

    def size(self):
        """
        Return the size (i.e. sequence length) of the cache.

        Not every cache is required to implement this, in which case the size
        will always be 0 (though the cache may not be empty).
        """
        return 0

    @property
    def nbytes(self):
        """Return the size of this cache in bytes"""
        raise NotImplementedError('Cache sub-class must implement nbytes')

    def empty(self):
        """
        Return if the cache is empty or not.
        """
        raise NotImplementedError('Cache sub-class must implement this.')

    @classmethod
    def from_state(cls, state):
        obj = cls.__new__(cls)
        obj.state = state
        return obj

KVCache.source:
class KVCache(_BaseCache):
    step = 256

    def __init__(self):
        self.keys = None
        self.values = None
        self.offset = 0

    def update_and_fetch(self, keys, values):
        prev = self.offset
        if self.keys is None or prev + keys.shape[2] > self.keys.shape[2]:
            B, n_kv_heads, _, k_head_dim = keys.shape
            v_head_dim = values.shape[3]
            n_steps = (self.step + keys.shape[2] - 1) // self.step
            k_shape = (B, n_kv_heads, n_steps * self.step, k_head_dim)
            v_shape = (B, n_kv_heads, n_steps * self.step, v_head_dim)
            new_k = mx.zeros(k_shape, keys.dtype)
            new_v = mx.zeros(v_shape, values.dtype)
            if self.keys is not None:
                if prev % self.step != 0:
                    self.keys = self.keys[..., :prev, :]
                    self.values = self.values[..., :prev, :]
                self.keys = mx.concatenate([self.keys, new_k], axis=2)
                self.values = mx.concatenate([self.values, new_v], axis=2)
            else:
                self.keys, self.values = (new_k, new_v)
        self.offset += keys.shape[2]
        self.keys[..., prev:self.offset, :] = keys
        self.values[..., prev:self.offset, :] = values
        return self.keys_and_values()

    def keys_and_values(self):
        if self.offset < self.keys.shape[2]:
            return (self.keys[..., :self.offset, :], self.values[..., :self.offset, :])
        else:
            return (self.keys, self.values)

    def size(self):
        return self.offset

    @property
    def state(self):
        return (self.keys, self.values, self.offset)

    @state.setter
    def state(self, v):
        self.keys, self.values, self.offset = v

    def is_trimmable(self):
        return True

    def trim(self, n):
        n = min(self.offset, n)
        self.offset -= n
        return n

    def to_quantized(self, group_size: int=64, bits: int=4) -> QuantizedKVCache:
        quant_cache = QuantizedKVCache(group_size=group_size, bits=bits)
        quant_cache.offset = self.offset
        if self.keys is not None:
            quant_cache.keys = mx.quantize(self.keys, group_size=group_size, bits=bits)
            quant_cache.values = mx.quantize(self.values, group_size=group_size, bits=bits)
        return quant_cache

    def make_mask(self, *args, **kwargs):
        return create_attention_mask(*args, offset=self.offset, **kwargs)

    @classmethod
    def merge(_, caches):
        return BatchKVCache.merge(caches)

    def empty(self):
        return self.keys is None

    @property
    def nbytes(self):
        if self.keys is None:
            return 0
        return self.keys.nbytes + self.values.nbytes

RotatingKVCache.source:
class RotatingKVCache(_BaseCache):
    step = 256

    def __init__(self, max_size, keep=0):
        self.keep = keep
        self.keys = None
        self.values = None
        self.offset = 0
        self.max_size = max_size
        self._idx = 0

    def _trim(self, trim_size, v, append=None):
        to_cat = []
        if trim_size > 0:
            to_cat = [v[..., :self.keep, :], v[..., trim_size + self.keep:, :]]
        else:
            to_cat = [v]
        if append is not None:
            to_cat.append(append)
        return mx.concatenate(to_cat, axis=2)

    def _temporal_order(self, v):
        """
        Rearrange the cache into temporal order, slicing off the end if unused.
        """
        if self._idx == v.shape[2]:
            return v
        elif self._idx < self.offset:
            return mx.concatenate([v[..., :self.keep, :], v[..., self._idx:, :], v[..., self.keep:self._idx, :]], axis=2)
        else:
            return v[..., :self._idx, :]

    def _update_concat(self, keys, values):
        if self.keys is None:
            self.keys = keys
            self.values = values
        else:
            self.keys = self._temporal_order(self.keys)
            self.values = self._temporal_order(self.values)
            self._idx = self.keys.shape[2]
            trim_size = self._idx - self.max_size + 1
            self.keys = self._trim(trim_size, self.keys, keys)
            self.values = self._trim(trim_size, self.values, values)
        self.offset += keys.shape[2]
        self._idx = self.keys.shape[2]
        return (self.keys, self.values)

    def _update_in_place(self, keys, values):
        B, n_kv_heads, S, k_head_dim = keys.shape
        prev = self.offset
        if self.keys is None or (prev >= self.keys.shape[2] and self.keys.shape[2] < self.max_size):
            v_head_dim = values.shape[3]
            new_size = min(self.step, self.max_size - prev)
            k_shape = (B, n_kv_heads, new_size, k_head_dim)
            v_shape = (B, n_kv_heads, new_size, v_head_dim)
            new_k = mx.zeros(k_shape, keys.dtype)
            new_v = mx.zeros(v_shape, values.dtype)
            if self.keys is not None:
                self.keys = mx.concatenate([self.keys, new_k], axis=2)
                self.values = mx.concatenate([self.values, new_v], axis=2)
            else:
                self.keys, self.values = (new_k, new_v)
            self._idx = prev
        trim_size = self.keys.shape[2] - self.max_size
        if trim_size > 0:
            self.keys = self._trim(trim_size, self.keys)
            self.values = self._trim(trim_size, self.values)
            self._idx = self.max_size
        if self._idx == self.max_size:
            self._idx = self.keep
        self.keys[..., self._idx:self._idx + S, :] = keys
        self.values[..., self._idx:self._idx + S, :] = values
        self.offset += S
        self._idx += S
        return self.keys_and_values()

    def update_and_fetch(self, keys, values):
        if keys.shape[2] == 1:
            return self._update_in_place(keys, values)
        return self._update_concat(keys, values)

    def keys_and_values(self):
        if self.offset < self.keys.shape[2]:
            return (self.keys[..., :self.offset, :], self.values[..., :self.offset, :])
        else:
            return (self.keys, self.values)

    def size(self):
        return min(self.offset, self.max_size)

    @property
    def state(self):
        return (self.keys, self.values, self.offset, self.keep, self.max_size, self._idx)

    @state.setter
    def state(self, v):
        self.keys, self.values, self.offset, self.keep, self.max_size, self._idx = v

    def is_trimmable(self):
        return self.offset < self.max_size

    def trim(self, n):
        n = min(self.offset, n)
        self.offset -= n
        self._idx -= n
        return n

    def to_quantized(self, group_size: int=64, bits: int=4) -> QuantizedKVCache:
        raise NotImplementedError('RotatingKVCache Quantization NYI')

    def make_mask(self, N: int, window_size: Optional[int]=None, return_array: bool=False):
        if N > 1:
            window_size = window_size or self.max_size
            offset = min(self.max_size - 1, self.offset)
            if offset + N > window_size or return_array:
                return create_causal_mask(N, offset, window_size=window_size)
            else:
                return 'causal'
        else:
            if window_size is None:
                return None
            if self.offset >= window_size and self.max_size > window_size:
                idx = self._idx
                if idx >= self.max_size:
                    idx = 0
                if self.offset < self.max_size:
                    mask_size = self.offset + 1
                else:
                    mask_size = self.max_size
                mask = mx.arange(mask_size) >= mask_size - window_size
                mask = mx.roll(mask, shift=idx + 1)
                return mask

    @classmethod
    def merge(_, caches):
        return BatchRotatingKVCache.merge(caches)

    def empty(self):
        return self.keys is None

    @property
    def nbytes(self):
        if self.keys is None:
            return 0
        return self.keys.nbytes + self.values.nbytes

ProportionalRoPE.source:
class ProportionalRoPE(nn.Module):

    def __init__(self, dims: int, rotated_dims: int, traditional: bool=False, base: float=10000.0, factor: float=1.0):
        super().__init__()
        self.dims = dims
        self.traditional = traditional
        if rotated_dims > dims:
            raise ValueError('rotated_dims should be smaller than dims')
        exponents = mx.arange(0, rotated_dims, 2, dtype=mx.float32) / dims
        self._freqs = mx.concatenate([factor * base ** exponents, mx.full(((dims - rotated_dims) // 2,), mx.inf)])

    def __call__(self, x, offset=0):
        return mx.fast.rope(x, self.dims, traditional=self.traditional, base=None, scale=1.0, offset=offset, freqs=self._freqs)

initialize_rope.source:
def initialize_rope(dims, base, traditional, scaling_config: Optional[dict]=None, max_position_embeddings: Optional[int]=None):
    if scaling_config is not None:
        rope_type = scaling_config.get('type') or scaling_config.get('rope_type', 'default')
    else:
        rope_type = 'default'
    if rope_type in ['default', 'linear']:
        scale = 1 / scaling_config['factor'] if rope_type == 'linear' else 1.0
        return nn.RoPE(dims, traditional=traditional, base=base, scale=scale)
    elif rope_type == 'dynamic':
        return DynamicNTKScalingRoPE(dims=dims, max_position_embeddings=max_position_embeddings, traditional=traditional, base=base, factor=scaling_config['factor'])
    elif rope_type == 'llama3':
        return Llama3RoPE(dims=dims, max_position_embeddings=max_position_embeddings, traditional=traditional, base=base, scaling_config=scaling_config)
    elif rope_type in ('yarn', 'deepseek_yarn', 'telechat3-yarn'):
        scaling_factor = scaling_config['factor']
        rope_kwargs = {key: scaling_config[key] for key in ['original_max_position_embeddings', 'beta_fast', 'beta_slow', 'mscale', 'mscale_all_dim', 'truncate'] if key in scaling_config}
        return YarnRoPE(dims=dims, max_position_embeddings=max_position_embeddings, traditional=traditional, scaling_factor=scaling_factor, base=base, **rope_kwargs)
    elif rope_type == 'longrope':
        return SuScaledRoPE(dims=dims, base=base, max_position_embeddings=max_position_embeddings, original_max_position_embeddings=scaling_config['original_max_position_embeddings'], short_factor=scaling_config['short_factor'], long_factor=scaling_config['long_factor'])
    elif rope_type == 'proportional':
        return ProportionalRoPE(dims=dims, rotated_dims=int(dims * scaling_config.get('partial_rotary_factor', 1.0)), traditional=traditional, base=base, factor=scaling_config.get('factor', 1.0))
    elif rope_type == 'mrope':
        mrope_section = scaling_config.get('mrope_section', [])
        assert len(mrope_section) == 3, f'MRoPE currently only supports 3 sections, got {len(mrope_section)}.'
        return nn.RoPE(dims, traditional=traditional, base=base)
    else:
        raise ValueError(f'Unsupported RoPE type {rope_type}')

